  ('galar', '가라르도감', 'Galar Pokédex')
insert into public.pokedex_entries (dex, number, species_id, is_default, ko_description, en_description) values
  ('national', 3, 10364, false, '꽃에서 황홀한 향기가 퍼져 나와 싸우는 자의 기분을 달래준다.', 'A bewitching aroma wafts from its flower. The fragrance becalms those engaged in a battle.'),
  ('national', 6, 10365, false, '지상 1400m까지 날개를 사용해 날 수 있다. 고열의 불꽃을 내뿜는다.', 'Its wings can carry this Pokémon close to an altitude of 4,600 feet. It blows out fire at very high temperatures.'),
  ('national', 9, 10366, false, '등껍질의 로켓포에서 뿜어져 나오는 제트 수류는 두꺼운 철판도 뚫는다.', 'The rocket cannons on its shell fire jets of water capable of punching holes through thick steel.'),
  ('national', 12, 10367, false, '매일 꿀을 모으러 다닌다. 다리의 솜털에 꿀을 발라 둥지로 가지고 가는 습성이 있다.', 'It collects honey every day. It rubs honey onto the hairs on its legs to carry it back to its nest.'),
  ('national', 25, 10319, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 25, 10368, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 52, 10320, false, '이마의 금화가 더러워지지 않도록 바지런히 얼굴을 씻는다. 가라르의 나옹과는 사이가 나쁘다.', 'It washes its face regularly to keep the coin on its forehead spotless. It doesn’t get along with Galarian Meowth.'),
  ('national', 52, 10369, false, '이마의 금화가 더러워지지 않도록 바지런히 얼굴을 씻는다. 가라르의 나옹과는 사이가 나쁘다.', 'It washes its face regularly to keep the coin on its forehead spotless. It doesn’t get along with Galarian Meowth.'),
  ('national', 68, 10370, false, '4개의 팔은 생각하는 것보다 빠르게 반사적으로 움직이며 여러 발의 펀치를 날린다.', 'In close combat, its four arms afford it offensive and defensive supremacy. In but a blink, this valiant Pokémon can overwhelm its foes with more than 1,000 blows from its fists.'),
  ('national', 77, 10321, false, '포니타에게 인정받으면 타오르는 갈기를 만져도 뜨거움을 느끼지 않게 된다.', 'These Pokémon live in herds out in the grassland. Newborn foals lack their fiery manes, which will develop about an hour after birth.'),
  ('national', 78, 10322, false, '가장 발이 빠른 날쌩마가 리더가 되어 무리가 갈 장소나 달리는 속도를 정한다.', 'Fiery mane aglow, Rapidash darts like an arrow across the land. This prodigiously swift creature can traverse the vast region of Hisui in a day and a half.'),
  ('national', 79, 10323, false, '꼬리를 물에 담가두면 단맛이 배어 나오기 때문에 이를 미끼로 포켓몬을 유인해서 낚는다.', 'When this Pokémon’s tail is soaked in water, sweetness seeps from it. Slowpoke uses this trait to lure in and fish up other Pokémon.'),
  ('national', 80, 10324, false, '셀러에게 물린 충격으로 두 발로 걸을 수 있게 되었다. 셀러가 떨어지면 야돈으로 돌아간다고 한다.', 'Being bitten by a Shellder shocked this Pokémon into standing on two legs. If the Shellder lets go, it seems Slowbro will turn back into a Slowpoke.'),
  ('national', 83, 10325, false, '식물의 줄기로 싸운다. 줄기를 휘두르는 방식에 따라 몇 종류의 유파가 있는 듯하다.', 'They use a plant stalk as a weapon, but not all of them use it in the same way. Several distinct styles of stalk fighting have been observed.'),
  ('national', 94, 10371, false, '산에서 조난하면 목숨을 빼앗기 위해 어둠 속에서 나타난다고 한다.', 'Possesses potential victims'' shadows in an effort to steal away the victims'' lives. If your shadow begins to laugh, you must take hold of a protective charm posthaste!'),
  ('national', 99, 10372, false, '큰 집게는 뛰어난 파괴력을 지녔지만 너무 무거워서 싸우지 않을 때는 거추장스럽다.', 'Its oversized claw is very powerful, but when it’s not in battle, the claw just gets in the way.'),
  ('national', 110, 10326, false, '가라르의 또도가스보다 공기를 흡입하는 힘은 조금 약하지만 내뿜는 독소는 강력하다.', 'It can’t suck in air quite as well as a Galarian Weezing, but the toxins it creates are more potent than those of its counterpart.'),
  ('national', 122, 10327, false, '팬터마임이 특기다. 손가락에서 내보내는 파동으로 벽을 만들어 갖은 공격으로부터 몸을 지킨다.', 'The behavior of this clown-like Pokémon reminds one of pantomime. It creates invisible walls using a force emitted from its fingertips.'),
  ('national', 131, 10373, false, '추위에 강해서 얼음 바다에서도 끄떡없다. 피부는 매끈매끈하고 조금 차갑다.', 'Crossing icy seas is no issue for this cold-resistant Pokémon. Its smooth skin is a little cool to the touch.'),
  ('national', 133, 10374, false, '불안정한 유전자 덕분에 여러 가지 진화의 가능성을 가지고 있는 특수한 포켓몬.', 'Harbors the potential to evolve into manifold forms. Within Eevee lies the key to the mysteries of Pokémon evolution—I''m certain of it.'),
  ('national', 143, 10375, false, '위장이 튼튼해서 곰팡이가 피거나 썩은 것을 먹어도 배탈이 나지 않는다.', 'This glutton appears in villages without warning and devours the entirety of their rice granaries—such occurrences have long been counted among the gravest of disasters.'),
  ('national', 144, 10328, false, '얼음을 자유자재로 조종하는 힘을 가졌다. 영구 동토의 설산에 살고 있다고 한다.', 'This Pokémon can control ice at will. Articuno is said to live in snowy mountains riddled with permafrost.'),
  ('national', 145, 10329, false, '날개를 비비대면 바로 천둥이 친다고 전해지는 전설의 새포켓몬이다.', 'Zapdos is a legendary bird Pokémon. It’s said that when Zapdos rubs its feathers together, lightning will fall immediately after.'),
  ('national', 146, 10330, false, '아름답게 타오르는 날개로 산길을 비춰 조난자를 도왔다고 전해져 오고 있다.', 'There are stories of this Pokémon using its radiant, flame-cloaked wings to light up paths for those lost in the mountains.'),
  ('national', 199, 10331, false, '아무리 어려운 문제를 물어봐도 모두 해결해주지만 그 누구도 야도킹의 말을 이해하지 못한다.', 'Slowking can solve any problem presented to it, but no one can understand a thing Slowking says.'),
  ('national', 222, 10332, false, '따뜻한 바다에 서식한다. 태고에는 가라르 근해에서도 많은 수가 서식했었다.', 'These Pokémon live in warm seas. In prehistoric times, many lived in the oceans around the Galar region as well.'),
  ('national', 263, 10333, false, '가라르의 지그제구리가 다른 지역에 적응한 모습이다. 물건을 찾는 게 특기다.', 'Zigzagoon that adapted to regions outside Galar acquired this appearance. If you’ve lost something, this Pokémon can likely find it.'),
  ('national', 264, 10334, false, '뛰어난 순발력과 예리한 발톱으로 먹이의 숨통을 끊는다. 굽은 길을 달리는 게 서툴다.', 'It uses its explosive speed and razor-sharp claws to bring down prey. Running along winding paths is not its strong suit.'),
  ('national', 554, 10335, false, '자고 있을 때는 밀어도 당겨도 절대 쓰러지지 않는다. 길조의 모티브로 인기가 높다.', 'This popular symbol of good fortune will never fall over in its sleep, no matter how it’s pushed or pulled.'),
  ('national', 555, 10336, false, '체내의 불꽃이 타오를수록 파워가 올라간다. 그 온도는 1400도를 넘기도 한다.', 'This Pokémon’s power level rises along with the temperature of its fire, which can reach 2,500 degrees Fahrenheit.'),
  ('national', 555, 10337, false, '체내의 불꽃이 타오를수록 파워가 올라간다. 그 온도는 1400도를 넘기도 한다.', 'This Pokémon’s power level rises along with the temperature of its fire, which can reach 2,500 degrees Fahrenheit.'),
  ('national', 562, 10338, false, '고대인의 영혼이 포켓몬이 되어 태어났다. 자신의 얼굴을 아는 사람을 찾아 유적을 떠돈다.', 'The spirit of a person from a bygone age became this Pokémon. It rambles through ruins, searching for someone who knows its face.'),
  ('national', 569, 10376, false, '오른팔에서 내보내는 독액은 약한 생물이 맞으면 즉사할 정도로 위험하다.', 'The toxic liquid it launches from its right arm is so virulent that it can kill a weakened creature instantly.'),
  ('national', 618, 10339, false, '몸의 노란 무늬에서 강한 전기를 발산할 때 무슨 이유인지 살짝 웃고 있다.', 'For some reason, this Pokémon smiles slightly when it emits a strong electric current from the yellow markings on its body.'),
  ('national', 809, 10377, false, '원심력으로 힘을 더해서 날리는 묵직한 너트 펀치는 포켓몬 중 최강이라고 전해진다.', 'Centrifugal force is behind the punches of Melmetal’s heavy hex-nut arms. Melmetal is said to deliver the strongest punches of all Pokémon.'),
  ('national', 810, 810, true, '스틱으로 연타하여 공격한다. 굉장한 속도로 치다 보면 점점 텐션이 올라간다.', 'It attacks with rapid beats of its stick. As it strikes with amazing speed, it gets more and more pumped.'),
  ('national', 811, 811, true, '격렬한 비트를 내는데 열중한 나머지 싸움에서 상대가 기절해도 모른다.', 'When it’s drumming out rapid beats in battle, it gets so caught up in the rhythm that it won’t even notice that it’s already knocked out its opponent.'),
  ('national', 812, 812, true, '드럼 테크닉이 가장 뛰어난 자가 보스가 된다. 천성이 온화해서 그룹의 조화를 중히 여긴다.', 'The one with the best drumming techniques becomes the boss of the troop. It has a gentle disposition and values harmony among its group.'),
  ('national', 812, 10378, false, '드럼 테크닉이 가장 뛰어난 자가 보스가 된다. 천성이 온화해서 그룹의 조화를 중히 여긴다.', 'The one with the best drumming techniques becomes the boss of the troop. It has a gentle disposition and values harmony among its group.'),
  ('national', 813, 813, true, '싸울 준비가 되면 코끝과 발바닥의 볼록살에서 고열을 낸다.', 'It has special pads on the backs of its feet, and one on its nose. Once it’s raring to fight, these pads radiate tremendous heat.'),
  ('national', 814, 814, true, '손을 쓰지 않고 나뭇가지에서 나무열매를 따내고 리프팅한다. 발 기술을 연마하는 연습이다.', 'It kicks berries right off the branches of trees and then juggles them with its feet, practicing its footwork.'),
  ('national', 815, 815, true, '공수에 뛰어나고 응원을 받으면 더 뜨겁게 타오르지만 스탠드 플레이를 하다가 위기에 처하는 경우도 있다.', 'It’s skilled at both offense and defense, and it gets pumped up when cheered on. But if it starts showboating, it could put itself in a tough spot.'),
  ('national', 815, 10379, false, '공수에 뛰어나고 응원을 받으면 더 뜨겁게 타오르지만 스탠드 플레이를 하다가 위기에 처하는 경우도 있다.', 'It’s skilled at both offense and defense, and it gets pumped up when cheered on. But if it starts showboating, it could put itself in a tough spot.'),
  ('national', 816, 816, true, '젖으면 피부색이 변한다. 위장한 것처럼 모습이 보이지 않게 된다.', 'When it gets wet, its skin changes color, and this Pokémon becomes invisible as if it were camouflaged.'),
  ('national', 817, 817, true, '머리가 좋지만 귀찮음이 많다. 영역에 적이 다가오지 못하게 여기저기에 함정을 만들어 놓는다.', 'Highly intelligent but also very lazy, it keeps enemies out of its territory by laying traps everywhere.'),
  ('national', 818, 818, true, '손가락 끝에서 마하3의 스피드로 물대포를 쏜다. 눈의 얇은 막으로 급소를 간파해 꿰뚫어버린다.', 'Its nictitating membranes let it pick out foes’ weak points so it can precisely blast them with water that shoots from its fingertips at Mach 3.'),
  ('national', 818, 10380, false, '손가락 끝에서 마하3의 스피드로 물대포를 쏜다. 눈의 얇은 막으로 급소를 간파해 꿰뚫어버린다.', 'Its nictitating membranes let it pick out foes’ weak points so it can precisely blast them with water that shoots from its fingertips at Mach 3.'),
  ('national', 819, 819, true, '항상 나무열매를 먹고 있어 보기보다 튼튼하다. 나무열매를 노리고 밭에 출몰한다.', 'It eats berries nonstop—a habit that has made it more resilient than it looks. It’ll show up on farms, searching for yet more berries.'),
  ('national', 820, 820, true, '아무리 단단한 나무열매 껍질도 이빨로 아작아작 갉아 먹는다. 가라르에서 쉽게 볼 수 있는 포켓몬이다.', 'Common throughout the Galar region, this Pokémon has strong teeth and can chew through the toughest of berry shells.'),
  ('national', 821, 821, true, '작은 몸을 기민하게 날려 틈을 노리는 전법으로 몸집이 큰 상대를 농락한다.', 'Jumping nimbly about, this small-bodied Pokémon takes advantage of even the slightest opportunity to disorient larger opponents.'),
  ('national', 822, 822, true, '혹독한 싸움을 헤쳐 나와 상대의 역량을 정확히 판단하는 힘을 습득했다.', 'The lessons of many harsh battles have taught it how to accurately judge an opponent’s strength.'),
  ('national', 823, 823, true, '비행 능력이 뛰어나고 매우 영리해 가라르지방에서 하늘의 택시로 활약한다.', 'With their great intellect and flying skills, these Pokémon very successfully act as the Galar region’s airborne taxi service.'),
  ('national', 823, 10381, false, '비행 능력이 뛰어나고 매우 영리해 가라르지방에서 하늘의 택시로 활약한다.', 'With their great intellect and flying skills, these Pokémon very successfully act as the Galar region’s airborne taxi service.'),
  ('national', 824, 824, true, '밭에서 자주 보이는 포켓몬이다. 몸에 난 털로 주위에서 일어나는 일을 감지한다.', 'Often found in gardens, this Pokémon has hairs on its body that it uses to assess its surroundings.'),
  ('national', 825, 825, true, '껍질 안에서 성장 중이다. 사이코 파워로 밖의 상태를 살피며 진화에 대비하고 있다.', 'As it grows inside its shell, it uses its psychic abilities to monitor the outside world and prepare for evolution.'),
  ('national', 826, 826, true, '사이코 파워를 발산해 주위를 조사한다. 관측 범위는 주변 10km에 달한다.', 'It emits psychic energy to observe and study what’s around it—and what’s around it can include things over six miles away.'),
  ('national', 826, 10382, false, '사이코 파워를 발산해 주위를 조사한다. 관측 범위는 주변 10km에 달한다.', 'It emits psychic energy to observe and study what’s around it—and what’s around it can include things over six miles away.'),
  ('national', 827, 827, true, '조심성이 많고 교활하다. 먹이를 훔치고는 꼬리로 발자국을 지우며 도망간다.', 'Cunning and cautious, this Pokémon survives by stealing food from others. It erases its tracks with swipes of its tail as it makes off with its plunder.'),
  ('national', 828, 828, true, '가벼운 몸과 날카로운 발톱으로 먹이나 알을 훔치며 돌아다닌다. 펄스멍이 천적이다.', 'With a lithe body and sharp claws, it goes around stealing food and eggs. Boltund is its natural enemy.'),
  ('national', 829, 829, true, '산들바람에 빙글빙글 돌면서 즐겁게 노래하는 귀여운 모습에 반해서 키우는 사람이 많다.', 'It whirls around in the wind while singing a joyous song. This delightful display has charmed many into raising this Pokémon.'),
  ('national', 830, 830, true, '머리의 솜털로 만든 실은 윤이 나고 매우 아름답다. 가라르지방의 특산품이다.', 'The cotton on the head of this Pokémon can be spun into a glossy, gorgeous yarn—a Galar regional specialty.'),
  ('national', 831, 831, true, '털이 많이 자라면 움직이지 못한다. 우르의 털로 짠 천은 놀라울 정도로 튼튼하다.', 'If its fleece grows too long, Wooloo won’t be able to move. Cloth made with the wool of this Pokémon is surprisingly strong.'),
  ('national', 832, 832, true, '늠름하게 자란 뿔은 이성에게 어필하기 위한 것이다. 무기로는 사용하지 않는다.', 'Its majestic horns are meant only to impress the opposite gender. They never see use in battle.'),
  ('national', 833, 833, true, '머리 뿔은 바위처럼 단단하다. 뿔로 싸우다가 풀이 죽은 틈에 덥석 물고 놓지 않는다.', 'It starts off battles by attacking with its rock-hard horn, but as soon as the opponent flinches, this Pokémon bites down and never lets go.'),
  ('national', 834, 834, true, '목을 자유자재로 늘이고 줄인다. 떨어져 있는 곳에서 목을 단번에 늘여 날카로운 이빨로 적의 숨통을 끊는다.', 'This Pokémon rapidly extends its retractable neck to sink its sharp fangs into distant enemies and take them down.'),
  ('national', 834, 10383, false, '목을 자유자재로 늘이고 줄인다. 떨어져 있는 곳에서 목을 단번에 늘여 날카로운 이빨로 적의 숨통을 끊는다.', 'This Pokémon rapidly extends its retractable neck to sink its sharp fangs into distant enemies and take them down.'),
  ('national', 835, 835, true, '간식에 끌려 사람의 일을 돕는 먹보다. 탁탁 튀는 전기를 두르고 계속 달린다.', 'This gluttonous Pokémon only assists people with their work because it wants treats. As it runs, it crackles with electricity.'),
  ('national', 836, 836, true, '전기의 힘으로 다릿심을 강하게 키운다. 최고 속도는 시속 90km를 가볍게 넘긴다.', 'It sends electricity through its legs to boost their strength. Running at top speed, it easily breaks 50 mph.'),
  ('national', 837, 837, true, '바위투성이의 거친 길을 아무렇지도 않게 일륜차처럼 달린다. 석탄을 태워서 살고 있다.', 'It can race around like a unicycle, even on rough, rocky terrain. Burning coal sustains it.'),
  ('national', 838, 838, true, '다리를 고속으로 회전시켜 시속 30km로 달린다. 섭씨 1000도의 불꽃을 내뿜는다.', 'By rapidly rolling its legs, it can travel at over 18 mph. The temperature of the flames it breathes exceeds 1,800 degrees Fahrenheit.'),
  ('national', 839, 839, true, '싸우게 되면 석탄으로 된 산이 새빨갛게 타올라 불똥을 흩뿌려 주위를 태운다.', 'While it’s engaged in battle, its mountain of coal will burn bright red, sending off sparks that scorch the surrounding area.'),
  ('national', 839, 10384, false, '싸우게 되면 석탄으로 된 산이 새빨갛게 타올라 불똥을 흩뿌려 주위를 태운다.', 'While it’s engaged in battle, its mountain of coal will burn bright red, sending off sparks that scorch the surrounding area.'),
  ('national', 840, 840, true, '태어나면 사과 안으로 숨어든다. 안을 파먹으면서 성장하고 사과 맛이 진화를 결정한다.', 'As soon as it’s born, it burrows into an apple. Not only does the apple serve as its food source, but the flavor of the fruit determines its evolution.'),
  ('national', 841, 841, true, '사과 껍질로 된 날개로 날며 강산성의 타액을 뱉는다. 사과의 형태로 변형한다.', 'It flies on wings of apple skin and spits a powerful acid. It can also change its shape into that of an apple.'),
  ('national', 841, 10385, false, '사과 껍질로 된 날개로 날며 강산성의 타액을 뱉는다. 사과의 형태로 변형한다.', 'It flies on wings of apple skin and spits a powerful acid. It can also change its shape into that of an apple.'),
  ('national', 842, 842, true, '달콤한 꿀로 몸이 둘러싸여 있다. 등의 껍질은 특히 더 달콤해서 옛날에는 어린이 간식이었다.', 'Its body is covered in sweet nectar, and the skin on its back is especially yummy. Children used to have it as a snack.'),
  ('national', 842, 10386, false, '달콤한 꿀로 몸이 둘러싸여 있다. 등의 껍질은 특히 더 달콤해서 옛날에는 어린이 간식이었다.', 'Its body is covered in sweet nectar, and the skin on its back is especially yummy. Children used to have it as a snack.'),
  ('national', 843, 843, true, '콧구멍으로 모래를 분사한다. 적의 눈을 속이고 그 틈에 땅속으로 숨어들어 몸을 숨긴다.', 'It spews sand from its nostrils. While the enemy is blinded, it burrows into the ground to hide.'),
  ('national', 844, 844, true, '독특한 똬리 형태는 모래주머니의 모래를 더 효율적으로 분사하기 위함이다.', 'Its unique style of coiling allows it to blast sand out of its sand sac more efficiently.'),
  ('national', 844, 10387, false, '독특한 똬리 형태는 모래주머니의 모래를 더 효율적으로 분사하기 위함이다.', 'Its unique style of coiling allows it to blast sand out of its sand sac more efficiently.'),
  ('national', 845, 845, true, '먹보이다. 먹이인 찌로꼬치를 통째로 삼키지만 가끔 실수로 다른 포켓몬을 먹어버린다.', 'This hungry Pokémon swallows Arrokuda whole. Occasionally, it makes a mistake and tries to swallow a Pokémon other than its preferred prey.'),
  ('national', 845, 10341, false, '먹보이다. 먹이인 찌로꼬치를 통째로 삼키지만 가끔 실수로 다른 포켓몬을 먹어버린다.', 'This hungry Pokémon swallows Arrokuda whole. Occasionally, it makes a mistake and tries to swallow a Pokémon other than its preferred prey.'),
  ('national', 845, 10342, false, '먹보이다. 먹이인 찌로꼬치를 통째로 삼키지만 가끔 실수로 다른 포켓몬을 먹어버린다.', 'This hungry Pokémon swallows Arrokuda whole. Occasionally, it makes a mistake and tries to swallow a Pokémon other than its preferred prey.'),
  ('national', 846, 846, true, '배가 불러서 현저히 움직임이 둔해지면 윽우지가 통째로 삼켜버린다.', 'After it’s eaten its fill, its movements become extremely sluggish. That’s when Cramorant swallows it up.'),
  ('national', 847, 847, true, '꼬리지느러미를 회전시켜 단번에 돌격한다. 100노트를 넘는 속도로 먹이를 관통한다.', 'It spins its tail fins to propel itself, surging forward at speeds of over 100 knots before ramming prey and spearing into them.'),
  ('national', 848, 848, true, '독소를 화학 변화시켜 전기를 만들어 낸다. 전력은 약하지만 찌릿찌릿 마비된다.', 'It manipulates the chemical makeup of its poison to produce electricity. The voltage is weak, but it can cause a tingling paralysis.'),
  ('national', 849, 849, true, '호전적이며 성미가 급하다. 고인 물을 벌컥벌컥 마셔서 물속의 독소를 흡수한다.', 'This short-tempered and aggressive Pokémon chugs stagnant water to absorb any toxins it might contain.'),
  ('national', 849, 10343, false, '호전적이며 성미가 급하다. 고인 물을 벌컥벌컥 마셔서 물속의 독소를 흡수한다.', 'This short-tempered and aggressive Pokémon chugs stagnant water to absorb any toxins it might contain.'),
  ('national', 849, 10388, false, '호전적이며 성미가 급하다. 고인 물을 벌컥벌컥 마셔서 물속의 독소를 흡수한다.', 'This short-tempered and aggressive Pokémon chugs stagnant water to absorb any toxins it might contain.'),
  ('national', 849, 10397, false, '호전적이며 성미가 급하다. 고인 물을 벌컥벌컥 마셔서 물속의 독소를 흡수한다.', 'This short-tempered and aggressive Pokémon chugs stagnant water to absorb any toxins it might contain.'),
  ('national', 850, 850, true, '발열된 몸으로 먹이를 세게 조른다. 알맞게 구워지면 우적우적 먹어버린다.', 'It wraps prey up with its heated body, cooking them in its coils. Once they’re well-done, it will voraciously nibble them down to the last morsel.'),
  ('national', 851, 851, true, '공격적인 성질을 가졌다. 탄 몸도 위험하지만 큰 이빨도 날카롭다.', 'While its burning body is already dangerous on its own, this excessively hostile Pokémon also has large and very sharp fangs.'),
  ('national', 851, 10389, false, '공격적인 성질을 가졌다. 탄 몸도 위험하지만 큰 이빨도 날카롭다.', 'While its burning body is already dangerous on its own, this excessively hostile Pokémon also has large and very sharp fangs.'),
  ('national', 852, 852, true, '세 살 아이 정도의 지능을 가졌다. 촉수는 잘 끊어지지만 재생되기 때문에 신경 쓰지 않는다.', 'Its tentacles tear off easily, but it isn’t alarmed when that happens—it knows they’ll grow back. It’s about as smart as a three-year-old.'),
  ('national', 853, 853, true, '자신의 실력을 시험하기 위해 육지로 올라가 대전 상대를 찾는다. 싸움이 끝나면 바다로 돌아간다.', 'Searching for an opponent to test its skills against, it emerges onto land. Once the battle is over, it returns to the sea.'),
  ('national', 854, 854, true, '거처로 삼고 있는 찻잔은 유명한 골동품 식기다. 위작이 많이 나돌고 있다.', 'The teacup in which this Pokémon makes its home is a famous piece of antique tableware. Many forgeries are in circulation.'),
  ('national', 855, 855, true, '남겨진 홍차를 발견하면 자신의 몸을 흘러 들어가게 한다. 그 홍차는 포트데스가 된다.', 'Leaving leftover black tea unattended is asking for this Pokémon to come along and pour itself into it, turning the tea into a new Polteageist.'),
  ('national', 856, 856, true, '인적이 드문 곳을 좋아한다. 강한 감정이 느껴지면 쏜살같이 도망쳐버린다.', 'If this Pokémon senses a strong emotion, it will run away as fast as it can. It prefers areas without people.'),
  ('national', 857, 857, true, '머리의 술로 상대를 때려 꼼짝 못 하게 한다. 프로복서조차 한 방에 KO되는 파괴력이다.', 'Using the braids on its head, it pummels foes to get them to quiet down. One blow from those braids would knock out a professional boxer.'),
  ('national', 858, 858, true, '숲의 마녀라는 별명을 가졌다. 소란을 피우면 촉수의 손톱에 찢겨질지도 모른다.', 'If you’re too loud around it, you risk being torn apart by the claws on its tentacle. This Pokémon is also known as the Forest Witch.'),
  ('national', 858, 10390, false, '숲의 마녀라는 별명을 가졌다. 소란을 피우면 촉수의 손톱에 찢겨질지도 모른다.', 'If you’re too loud around it, you risk being torn apart by the claws on its tentacle. This Pokémon is also known as the Forest Witch.'),
  ('national', 859, 859, true, '민가에 숨어들어 도둑질을 하고 속상해하는 사람의 마이너스 에너지도 얻는다.', 'It sneaks into people’s homes, stealing things and feasting on the negative energy of the frustrated occupants.'),
  ('national', 860, 860, true, '못된 꾀를 내어 밤에 숲으로 꾀어내려 한다. 농작물을 키우는 힘을 갖고 있는 듯하다.', 'With sly cunning, it tries to lure people into the woods. Some believe it to have the power to make crops grow.'),
  ('national', 861, 861, true, '머리카락은 근섬유의 역할을 하며 매듭이 풀어지면 촉수와 같은 움직임으로 상대를 묶어버린다.', 'Its hairs work like muscle fibers. When its hairs unfurl, they latch on to opponents, ensnaring them as tentacles would.'),
  ('national', 861, 10391, false, '머리카락은 근섬유의 역할을 하며 매듭이 풀어지면 촉수와 같은 움직임으로 상대를 묶어버린다.', 'Its hairs work like muscle fibers. When its hairs unfurl, they latch on to opponents, ensnaring them as tentacles would.'),
  ('national', 862, 862, true, '싸움을 반복하면서 진화한다. 팔을 크로스하고 우렁차게 외치면 어떤 상대라도 풀죽게 된다.', 'It evolved after experiencing numerous fights. While crossing its arms, it lets out a shout that would make any opponent flinch.'),
  ('national', 863, 863, true, '싸움에 열중해 진화한 결과 펴면 단검으로 변하는 위험한 발톱을 얻었다.', 'After many battles, it evolved dangerous claws that come together to form daggers when extended.'),
  ('national', 864, 864, true, '혼을 감싸는 영체의 몸은 주의가 필요하다. 만지면 돌처럼 움직일 수 없게 된다.', 'Be cautious of the ectoplasmic body surrounding its soul. You’ll become stiff as stone if you touch it.'),
  ('national', 865, 865, true, '단단한 파잎으로 공격을 받아넘기고 날카로운 줄기로 반격한다. 파는 무기인 동시에 식재료다.', 'After deflecting attacks with its hard leaf shield, it strikes back with its sharp leek stalk. The leek stalk is both weapon and food.'),
  ('national', 866, 866, true, '유머러스한 움직임으로 모두에게 인기가 높다. 배의 무늬에서 사이코 파워를 방출한다.', 'Its amusing movements make it very popular. It releases its psychic power from the pattern on its belly.'),
  ('national', 867, 867, true, '그림자 같은 몸을 만지면 안 된다. 그림에 새겨진 무서운 기억을 보게 되기 때문이다.', 'Never touch its shadowlike body, or you’ll be shown the horrific memories behind the picture carved into it.'),
  ('national', 868, 868, true, '마빌크가 모습을 보인 디저트 가게는 크게 번창한다고 전해지고 있다.', 'They say that any patisserie visited by Milcery is guaranteed success and good fortune.'),
  ('national', 869, 869, true, '손에서 나오는 크림은 마휘핑이 행복할 때 단맛과 감칠맛이 깊어진다.', 'When Alcremie is content, the cream it secretes from its hands becomes sweeter and richer.'),
  ('national', 869, 10346, false, '손에서 나오는 크림은 마휘핑이 행복할 때 단맛과 감칠맛이 깊어진다.', 'When Alcremie is content, the cream it secretes from its hands becomes sweeter and richer.'),
